import React,{useState,useEffect} from 'react';

import * as Dialog from '@radix-ui/react-dialog';
import {House,CoatHanger,Sparkle,ShoppingBag,CalendarBlank,ChatCircle,MapPin,Heart,Plus,MagnifyingGlass,ArrowRight,Check,X,Sun,Moon,SlidersHorizontal,Camera,Envelope,LinkSimple,ArrowDown,Users,Compass,BookmarkSimple,Tray,Export,ShieldCheck,DotsThree,CaretLeft,CaretRight,AirplaneTilt,Palette,Stack,ArrowsLeftRight,UserCircle,PaperPlaneTilt,Bell,Ruler,Eye,Pause,Play,Cloud,CloudRain,CloudLightning,Snowflake,CloudFog} from '@phosphor-icons/react';
import rawCatalog from './catalog.json';
import {officialEvents,eventCalendar} from './events.mjs';
